PRAGMA foreign_keys = ON;
CREATE TABLE emerging_monthly_revenue (snapshot_id TEXT NOT NULL REFERENCES source_snapshots(snapshot_id) ON DELETE CASCADE, company_code TEXT NOT NULL, company_name TEXT NOT NULL, industry TEXT NOT NULL, report_date TEXT, revenue_year_month TEXT NOT NULL, current_month_revenue_thousands_twd TEXT NOT NULL, previous_month_revenue_thousands_twd TEXT, previous_year_same_month_revenue_thousands_twd TEXT, month_over_month_percent TEXT, year_over_year_percent TEXT, current_year_cumulative_revenue_thousands_twd TEXT, previous_year_cumulative_revenue_thousands_twd TEXT, cumulative_year_over_year_percent TEXT, source_record_identity TEXT NOT NULL, source_id TEXT NOT NULL, resource_id TEXT NOT NULL, fetched_at TEXT NOT NULL, response_hash TEXT NOT NULL, PRIMARY KEY(snapshot_id,source_record_identity), UNIQUE(snapshot_id,company_code,revenue_year_month));
CREATE TABLE public_company_profiles (snapshot_id TEXT NOT NULL REFERENCES source_snapshots(snapshot_id) ON DELETE CASCADE, company_code TEXT NOT NULL, company_name TEXT NOT NULL, company_short_name TEXT NOT NULL, unified_business_number TEXT NOT NULL, industry_code TEXT, industry_name TEXT NOT NULL, establishment_date TEXT, company_address TEXT NOT NULL, company_phone TEXT, company_website TEXT NOT NULL, public_offering_date TEXT, source_record_identity TEXT NOT NULL, source_id TEXT NOT NULL, resource_id TEXT NOT NULL, fetched_at TEXT NOT NULL, response_hash TEXT NOT NULL, PRIMARY KEY(snapshot_id,source_record_identity), UNIQUE(snapshot_id,company_code));
CREATE TABLE bond_issuances (snapshot_id TEXT NOT NULL REFERENCES source_snapshots(snapshot_id) ON DELETE CASCADE, bond_code TEXT NOT NULL, bond_name TEXT NOT NULL, issuer_company_code TEXT NOT NULL, issuer_company_name TEXT NOT NULL, issue_date TEXT NOT NULL, listing_date TEXT, maturity_date TEXT NOT NULL, issue_amount TEXT NOT NULL, current_outstanding_balance TEXT NOT NULL, coupon_rate TEXT, guarantee_status TEXT NOT NULL, initial_conversion_price TEXT, conversion_start_date TEXT, conversion_end_date TEXT, underwriter TEXT, trustee TEXT, latest_balance_change_date TEXT, latest_balance_change_reason TEXT, offering_method TEXT, official_data_date TEXT NOT NULL, source_record_identity TEXT NOT NULL, source_id TEXT NOT NULL, resource_id TEXT NOT NULL, fetched_at TEXT NOT NULL, response_hash TEXT NOT NULL, PRIMARY KEY(snapshot_id,source_record_identity), UNIQUE(snapshot_id,bond_code), CHECK(CAST(current_outstanding_balance AS REAL) <= CAST(issue_amount AS REAL)));
CREATE TABLE bond_put_rights (snapshot_id TEXT NOT NULL, bond_code TEXT NOT NULL, sequence INTEGER NOT NULL CHECK(sequence >= 1), put_date TEXT NOT NULL, put_price TEXT NOT NULL, PRIMARY KEY(snapshot_id,bond_code,sequence), FOREIGN KEY(snapshot_id,bond_code) REFERENCES bond_issuances(snapshot_id,bond_code) ON DELETE CASCADE);
CREATE TABLE listing_applications (snapshot_id TEXT NOT NULL REFERENCES source_snapshots(snapshot_id) ON DELETE CASCADE, source_record_identity TEXT NOT NULL, official_index TEXT NOT NULL, company_code TEXT NOT NULL, company_short_name TEXT NOT NULL, application_date TEXT NOT NULL, application_capital_thousands_twd TEXT, listing_review_date TEXT, board_approval_date TEXT, listing_contract_approval_or_filing_date TEXT, listing_date TEXT, note TEXT NOT NULL, chronology_status TEXT NOT NULL CHECK(chronology_status IN ('complete','partial')), source_id TEXT NOT NULL, resource_id TEXT NOT NULL, fetched_at TEXT NOT NULL, response_hash TEXT NOT NULL, PRIMARY KEY(snapshot_id,source_record_identity), UNIQUE(snapshot_id,company_code,application_date));
CREATE TABLE listing_application_underwriters (snapshot_id TEXT NOT NULL, source_record_identity TEXT NOT NULL, sequence INTEGER NOT NULL CHECK(sequence >= 1), underwriter_name TEXT NOT NULL, PRIMARY KEY(snapshot_id,source_record_identity,sequence), FOREIGN KEY(snapshot_id,source_record_identity) REFERENCES listing_applications(snapshot_id,source_record_identity) ON DELETE CASCADE);
CREATE INDEX idx_revenue_company_month ON emerging_monthly_revenue(company_code,revenue_year_month); CREATE INDEX idx_profiles_company ON public_company_profiles(company_code); CREATE INDEX idx_bonds_maturity ON bond_issuances(maturity_date); CREATE INDEX idx_bonds_issuer ON bond_issuances(issuer_company_code); CREATE INDEX idx_applications_company_date ON listing_applications(company_code,application_date); CREATE INDEX idx_applications_listing_date ON listing_applications(listing_date);
